		/** 
		 * Tests creating a new Category.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Category");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Category" );

			try {            
				Category entity = CategoryService.getCategoryInstance().createCategory( generateNewEntity() );
				thePrimaryKey = entity.getCategoryId();
				LOGGER.info( "-- Successfully created a Category with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Category. 
		 */
		public Category testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Category" );

			Category entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Category with primary key" );
			msg.append( thePrimaryKey );
			
			CategoryFetchOneSummary fetchOneSummary = new CategoryFetchOneSummary( thePrimaryKey );

			try {
				entity = CategoryService.getCategoryInstance().getCategory( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Category " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Category.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Category." );

			StringBuilder msg = new StringBuilder( "Failed to update a Category : " );        
			Category entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Category." );

				// for use later on...
				thePrimaryKey = entity.getCategoryId();

				CategoryService proxy = CategoryService.getCategoryInstance();            
				proxy.updateCategory( entity );   

				LOGGER.info( "-- Successfully saved Category - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Category.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Category." );

			try{
			    Category entity = testRead(); 
				CategoryService.getCategoryInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Category with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Category with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Categorys.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Categorys:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Category : " );        
			List<Category> collection  = null;

			try {
				// call the static get method on the CategoryService
				collection = CategoryService.getCategoryInstance().getAllCategory();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Category entity = null;            
					Iterator<Category> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getCategoryId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

